@orders_bp.route("/search", methods=["GET"])
@require_auth
def search_orders():
    q = request.args.get("q", "")
    session = get_session()
    rows = session.execute(
        text(
            "SELECT id, user_id, status, total FROM orders "
            "WHERE user_id = :uid AND shipping_address LIKE :pattern"
        ),
        {"uid": g.current_user.id, "pattern": f"%{q}%"},
    )
    return jsonify([dict(r._mapping) for r in rows])

def is_owner_or_admin(user: User, owner_id: int) -> bool:
    """Ownership check used for per-object access (orders, profiles)."""
    return user.id == owner_id or user.role == "admin"

